B.a6u=new A.aR(57531,"MaterialIcons",!1)
B.aqm=new A.bm([B.b_,"Une rencontre ou un nouveau d\xe9part que tu provoques toi-m\xeame.",B.b0,"Un projet qui d\xe9marre : tu as en main tous les outils pour r\xe9ussir.",B.b1,"Une \xe9nergie neuve, \xe0 canaliser plut\xf4t qu'\xe0 disperser.",B.b2,"Le plaisir de cr\xe9er, d'apprendre, de jouer avec la vie."],t.Q)
B.UR=new A.et(1,"Le Bateleur",B.a6u,"l'habilet\xe9","Les promesses brillantes cachent parfois des tours de passe-passe.",B.aqm,!0)
B.a7_=new A.aR(58333,"MaterialIcons",!1)
B.aqq=new A.bm([B.b_,"Un sentiment discret, m\xfbri en secret, qui attend son heure.",B.b0,"La prudence et l'\xe9tude avant toute signature.",B.b1,"\xc9coute ton corps : il murmure avant de crier.",B.b2,"La paix des choses int\xe9rieures, des livres et des retraites."],t.Q)
