B.a6V=new A.aR(58259,"MaterialIcons",!1)
B.aqf=new A.bm([B.b_,"Une passion lumineuse, une s\xe9duction s\xfbre d'elle-m\xeame.",B.b0,"Des id\xe9es qui rapportent : la cr\xe9ativit\xe9 devient monnaie.",B.b1,"Une belle vitalit\xe9, un renouveau comme un printemps.",B.b2,"L'abondance, la beaut\xe9, le plaisir de recevoir."],t.Q)
