B.a7I=new A.aR(984983,"MaterialIcons",!1)
B.aqi=new A.bm([B.b_,"Un retournement de situation, une rencontre due au hasard.",B.b0,"Un coup de chance, un gain inattendu\u2026 \xe0 saisir vite.",B.b1,"Un cycle qui se termine, un autre plus favorable commence.",B.b2,"Le vent tourne enfin en ta faveur."],t.Q)
