B.a78=new A.aR(58529,"MaterialIcons",!1)
B.aqh=new A.bm([B.b_,"Une passion intense, apprivois\xe9e par la douceur.",B.b0,"Tu as l'\xe9nergie de mener \xe0 bien une affaire difficile.",B.b1,"Une grande vitalit\xe9, une r\xe9sistance \xe0 toute \xe9preuve.",B.b2,"La fiert\xe9 tranquille de celui qui ne craint plus ses d\xe9mons."],t.Q)
