B.a7f=new A.aR(58735,"MaterialIcons",!1)
B.aqs=new A.bm([B.b_,"Une relation en suspens : regarde-la sous un autre angle.",B.b0,"Des projets bloqu\xe9s, \xe0 repenser plut\xf4t qu'\xe0 forcer.",B.b1,"Une pause impos\xe9e, qui cache une le\xe7on.",B.b2,"La paix vient de ce que tu acceptes de ne plus retenir."],t.Q)
