B.a6O=new A.aR(58147,"MaterialIcons",!1)
B.aqt=new A.bm([B.b_,"Une page se tourne ; sur ses cendres pousse un amour neuf.",B.b0,"Une rupture nette avec une situation qui ne te nourrissait plus.",B.b1,"Une profonde r\xe9g\xe9n\xe9ration, une mue.",B.b2,"La libert\xe9 de celui qui ose tout recommencer."],t.Q)
